manifest=[]
def esc(s): return html.escape(str(s))
def fmt(x,n=1): return f'{float(x):,.{n}f}'.replace(',','’').replace('.',',')
def rows(book,sheet):
 a=list(book[sheet].values); return [dict(zip(a[0],r)) for r in a[1:]]
def csvrows(name):
 with (core/'Tabellen'/name).open(encoding='utf-8-sig') as f:return list(csv.DictReader(f))
def mapping(id,title,path,selector,values,note=''):
 manifest.append(dict(id=id,title=title,source=Path(path).relative_to(R).as_posix(),selector=selector,values=values,note=note))   # repo-relativ, keine lokalen Pfade
def svg(id,title,subtitle,body,height=400):
 return f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1000 {height}" role="img" aria-labelledby="{id}-title {id}-desc"><title id="{id}-title">{esc(title)}</title><desc id="{id}-desc">{esc(subtitle)}</desc><rect width="1000" height="{height}" fill="#fff"/><style>text{{font-family:Arial,sans-serif;fill:#18332d}}.sub{{font-size:15px;fill:#485e57}}.label{{font-size:17px}}.value{{font-size:18px;font-weight:700}}</style><text x="32" y="38" font-size="23" font-weight="700">{esc(title)}</text><text x="32" y="65" class="sub">{esc(subtitle)}</text>{body}<text x="32" y="{height-18}" class="sub">FCSG · Vertraulich · Datenstand 12.09.2026 · {id}</text></svg>'''
charts={}
def save(id,title,subtitle,body,height=400):
 s=svg(id,title,subtitle,body,height); (D/f'{id}.svg').write_text(s,encoding='utf-8');charts[id]=s;return s
def text(x,y,s,cls='label'):return f'<text x="{x}" y="{y}" class="{cls}">{esc(s)}</text>'
def bar(id,title,subtitle,data,maxv,unit='',height=None):
 h=height or 140+len(data)*53;b=''
 for i,(label,val,display) in enumerate(data):
  y=97+i*53;b+=text(32,y+20,label)+f'<rect x="260" y="{y}" width="{val/maxv*540:.2f}" height="28" rx="2" fill="#176647"/>'+text(280+val/maxv*540,y+21,display,'value')
 b+=text(260,h-46,f'Balken beginnen bei 0 · {unit}','sub');return save(id,title,subtitle,b,h)
