mapping('G01','Kundenfranken je Saison',core/'Tabellen/saison_kpi.csv','wettbewerbe=SL; saison,spiele,kf_inkl',[{k:r[k] for k in ['saison','spiele','kf_inkl']} for r in sl],'Summe/Summe; inkl. MwSt.; letzte Saison nur vier Spiele')
