bar('G05','T-7 verbessert die Anwesenheitsprognose','Rolling Origin · 54 retrospektive Vorhersagen · mittlerer absoluter Fehler (MAE)',[('Nur Kontext',t7['mae_kontext'],fmt(t7['mae_kontext'],0)),('Kontext + T-7',t7['mae_kontext_plus_t7'],fmt(t7['mae_kontext_plus_t7'],0))],1600,'Anwesende; kein Massnahmeneffekt')
