N_UEBER=sum(1 for r in dk if r['einordnung_konsum'].startswith('über Erwartung')); N_UNTER=sum(1 for r in dk if r['einordnung_konsum'].startswith('unter Erwartung'))
KB={r['thema']:r for r in rows(v,'01_Kernbefunde')}
